import { createECDH } from 'node:crypto';
import { sendNotification } from 'web-push';
import { ApiError, CONSENT, hash, random, vault } from './security.mjs';
import { POWER_NOTICE_CONSENT } from './power-notice.mjs';

const HOUR = 3_600_000;
const MAX_DEVICES = 5;
const COLLECTION = 'bapmunnaNotificationDevices';

// Accept only TLS endpoints generated by supported browser push services. A
// user-provided URL must never turn the sender into a general HTTP client.
function deviceEndpoint(input) {
  let url;
  if (typeof input !== 'string' || input.length > 2048) throw new ApiError(400, 'invalid_subscription');
  try { url = new URL(input); } catch { throw new ApiError(400, 'invalid_subscription'); }
  const h = url.hostname;
  const trusted = h === 'fcm.googleapis.com' ||
    h === 'web.push.apple.com' || h.endsWith('.push.apple.com') ||
    h === 'updates.push.services.mozilla.com' ||
    h.endsWith('.notify.windows.com');
  if (!trusted || url.protocol !== 'https:' || url.port || url.username || url.password ||
      url.hash || url.pathname.length < 2 || url.href !== input) throw new ApiError(400, 'invalid_subscription');
  return url.href;
}

function decodeKey(value, size) {
  if (typeof value !== 'string' || !/^[\w-]+$/.test(value)) throw new ApiError(400, 'invalid_subscription');
  const bytes = Buffer.from(value, 'base64url');
  if (bytes.length !== size || bytes.toString('base64url') !== value) throw new ApiError(400, 'invalid_subscription');
  return bytes;
}

function subscription(input) {
  const endpoint = deviceEndpoint(input?.endpoint);
  const pub = decodeKey(input?.keys?.p256dh, 65);
  decodeKey(input?.keys?.auth, 16);
  if (pub[0] !== 4) throw new ApiError(400, 'invalid_subscription');
  try {
    const check = createECDH('prime256v1');
    check.generateKeys();
    check.computeSecret(pub);
  } catch { throw new ApiError(400, 'invalid_subscription'); }
  return { endpoint, keys: { p256dh: input.keys.p256dh, auth: input.keys.auth } };
}

export function vapidKeys(env) {
  if (!env.WEB_PUSH_PRIVATE_KEY) return null;
  const signer = createECDH('prime256v1');
  signer.setPrivateKey(decodeKey(env.WEB_PUSH_PRIVATE_KEY, 32));
  return { privateKey: env.WEB_PUSH_PRIVATE_KEY, publicKey: signer.getPublicKey('base64url') };
}

export function createNotifier({ db, store, config, keys, verifyAccount, now = Date.now, send = sendNotification }) {
  if (!keys) return null;
  const devices = db.collection(COLLECTION);
  const protect = vault(config.key);
  const sendOptions = { vapidDetails: { subject: config.origin, ...keys }, timeout: 4000, urgency: 'normal' };
  const forOwner = uid => devices.where('uid', '==', uid).limit(MAX_DEVICES);
  function reference(endpoint) { return devices.doc(hash(deviceEndpoint(endpoint))); }
  function aad(uid, device) { return `web-push:${uid}:${device.id}`; }

  async function remove(uid, device, revision) {
    await db.runTransaction(async tx => {
      const current = (await tx.get(device)).data();
      if (current?.uid === uid && (!revision || current.revision === revision)) tx.delete(device);
    });
  }

  async function register(uid, authTime, raw) {
    const sub = subscription(raw);
    const device = reference(sub.endpoint);
    await store.verifyConsent(uid);
    const encrypted = protect.seal(sub, aad(uid, device));
    await db.runTransaction(async tx => {
      const current = (await tx.get(device)).data();
      if (current && current.uid !== uid) throw new ApiError(409, 'different_device_owner');
      if (!current && (await tx.get(forOwner(uid))).size >= MAX_DEVICES) throw new ApiError(409, 'device_limit');
      // Re-registering this endpoint never resets its cooldown or past-event boundary.
      tx.set(device, { ...(current ?? { enrolledAt: now() }), uid, authTime, encrypted, revision: random() });
    });
    return { registered: true };
  }

  async function sendDevice(uid, device, kind, at) {
    const check = kind === 'delivery_test';
    const attempt = random();
    const reserved = await db.runTransaction(async tx => {
      const saved = (await tx.get(device)).data();
      if (saved?.uid !== uid) return null;
      if (check && saved.lastTestAt > now() - 60_000) throw new ApiError(429, 'test_too_soon');
      if (!check && (at <= saved.enrolledAt || at <= (saved.lastSentAt ?? 0) ||
          (saved.lease?.until > now()))) return null;
      if (check) tx.update(device, { lastTestAt: now() });
      else tx.update(device, { lease: { attempt, until: now() + 20_000 } });
      return saved;
    });
    if (!reserved) return false;
    const update = async delivered => db.runTransaction(async tx => {
      const current = (await tx.get(device)).data();
      if (!check && current?.uid === uid && current.revision === reserved.revision &&
          current.lease?.attempt === attempt)
        tx.update(device, { lease: null, ...(delivered && { lastSentAt: Math.max(current.lastSentAt ?? 0, at) }) });
    });
    try {
      await verifyAccount(uid, reserved.authTime);
      await store.verifyConsent(uid);
      if (!check && (await eligibleSignal(uid)) !== at) { await update(false); return false; }
      const [latest] = await Promise.all([device.get(), store.verifyConsent(uid)]);
      const current = latest.data();
      if (current?.uid !== uid || current.revision !== reserved.revision ||
          (!check && current.lease?.attempt !== attempt)) return false;
      const time = new Date(at).toISOString();
      const payload = check ? { kind, tag: 'bapmunna-delivery-test', at: time } : {
        kind, at: time, tag: `cooker-${time}`, date: new Date(at + 9 * HOUR).toISOString().slice(0, 10),
      };
      await send(protect.open(current.encrypted, aad(uid, device)), JSON.stringify(payload),
        { ...sendOptions, TTL: check ? 60 : Math.max(1, Math.ceil((at + HOUR - now()) / 1000)) });
      await update(true);
      return true;
    } catch (error) {
      if ([404, 410].includes(error.statusCode)) {
        await remove(uid, device, reserved.revision);
        if (check) throw new ApiError(410, 'subscription_expired');
        return false;
      }
      await update(false);
      throw error;
    }
  }

  async function eligibleSignal(uid) {
    const c = await store.get(uid);
    const at = c?.powerNotice?.lastObservedAt;
    if (c?.uid !== uid || c.stage !== 'connected' || c.deviceIsVirtual !== false ||
        c.consentVersion !== CONSENT || c.powerNotice?.version !== POWER_NOTICE_CONSENT ||
        !Number.isSafeInteger(at) || at > now() || at <= now() - HOUR) return null;
    await verifyAccount(uid, c.authTime);
    await store.verifyConsent(uid);
    return at;
  }

  return {
    publicKey: keys.publicKey,
    async handle(uid, authTime, body) {
      if (body.op === 'register') return register(uid, authTime, body.subscription);
      const device = reference(body.endpoint);
      if (body.op === 'remove') { await remove(uid, device); return { registered: false }; }
      await store.verifyConsent(uid);
      if (body.op === 'check') return { registered: (await device.get()).data()?.uid === uid };
      if (body.op !== 'test') throw new ApiError(400, 'invalid_request');
      if (!await sendDevice(uid, device, 'delivery_test', now())) throw new ApiError(409, 'subscription_required');
      return { accepted: true };
    },
    // A repeated webhook or a later poll retries a failed send for the same
    // recent run. Its ID and notification tag remain stable on every device.
    async deliverCooker(uid) {
      const at = await eligibleSignal(uid);
      if (!at) return;
      const list = await forOwner(uid).get();
      await Promise.allSettled(list.docs.map(doc => sendDevice(uid, doc.ref, 'cooker_signal', at)));
    },
  };
}
